                    if (api.postComment) return api.postComment(key, comment);
                },
                moveToStatusOrMark: function(key, status, stage) {
                    rec.calls.push({ op: 'moveToStatusOrMark', key: key, status: status, stage: stage });
                    return { moved: true, marked: false };
                },
